package com.mvt.backApp.user.controller;
import com.mvt.backApp.common.dto.ApiResponse;import com.mvt.backApp.common.service.ApiResponseFactory;import com.mvt.backApp.user.dto.*;import com.mvt.backApp.user.service.AdminUserService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.UUID;
@RestController @RequestMapping("/api/admin/users") @RequiredArgsConstructor public class AdminUserController {private final AdminUserService service;private final ApiResponseFactory responses;
 @PostMapping("/admins") @PreAuthorize("hasAuthority('CREATE_ADMIN')") public ResponseEntity<ApiResponse<AdminUserService.ManagedUserResponse>> admin(@Valid @RequestBody CreateAdminRequest r){return ResponseEntity.status(201).body(responses.success("success.admin.created",201,service.createAdmin(r)));}
 @PutMapping("/{id}/permissions") @PreAuthorize("hasAuthority('ASSIGN_PERMISSIONS')") public ResponseEntity<ApiResponse<AdminUserService.ManagedUserResponse>> permissions(@PathVariable UUID id,@Valid @RequestBody AssignPermissionsRequest r){return ResponseEntity.ok(responses.success("success.permissions.updated",200,service.assign(id,r)));}
 @PutMapping("/{id}/password") @PreAuthorize("hasAuthority('CHANGE_AGENT_PASSWORD')") public ResponseEntity<ApiResponse<Void>> password(@PathVariable UUID id,@Valid @RequestBody ChangeManagedPasswordRequest r){service.changePassword(id,r);return ResponseEntity.ok(responses.success("success.password.updated",200,null));}}
